uint32 BotDataMgr::ArenaRolesForSpec(uint8 botClass, uint8 spec)
{
    switch (spec)
    {
        case BOT_SPEC_PALADIN_HOLY:
        case BOT_SPEC_PRIEST_DISCIPLINE:
        case BOT_SPEC_PRIEST_HOLY:
        case BOT_SPEC_SHAMAN_RESTORATION:
        case BOT_SPEC_DRUID_RESTORATION:
            return BOT_ROLE_HEAL | BOT_ROLE_RANGED;
        default:
            return DefaultRolesForClass(botClass, spec);
    }
}

